const jiraIssue = $('Jira > Get Issue').item.json;
const rawBrand = jiraIssue.fields?.customfield_11504?.[0]?.value || '';
const rawRegion = jiraIssue.fields?.customfield_11507?.[0]?.value || '';

const baserowData = $('Get Baserow Config').item.json;

if (!baserowData || Object.keys(baserowData).length === 0) {
  throw new Error(`No configuration found in Baserow for Brand: "${rawBrand}" and Region: "${rawRegion}". Please check Baserow records.`);
}

function extractVal(val) {
  if (Array.isArray(val)) return val[0]?.value || val[0]?.id || val[0] || '';
  if (val && typeof val === 'object') return val.value || val.id || val.name || '';
  return String(val || '').trim();
}

const brandCode = baserowData.Brand || baserowData.field_5176;
const brandName = baserowData.Brand_Name || rawBrand;
const region = (baserowData.Region || rawRegion || 'UFM').trim().toUpperCase();
const regionId = baserowData.Region_ID;
const domain = baserowData.Domain;

const playerId = extractVal(baserowData['PLAYER_ID 2'] || baserowData.PLAYER_ID || baserowData.field_5178);
const audienceCode = extractVal(baserowData.AUDIENCE_CODE || baserowData.field_5179);

const missing = [];
if (!brandCode) missing.push('Brand');
if (!regionId) missing.push('Region_ID');
if (!domain) missing.push('Domain');
if (!playerId) missing.push('PLAYER_ID');
if (!audienceCode) missing.push('AUDIENCE_CODE');

if (missing.length > 0) {
  throw new Error(`Missing required fields in Baserow config for (${rawBrand} / ${region}): ${missing.join(', ')}`);
}

let bucket = "Default";
let territory = "DEFAULT";

if (region === "LATAM") {
  bucket = "Latam";
  territory = "LATAM";
} else if (region === "CAN") {
  bucket = "Canada";
  territory = "CANADA";
}

const cleanDomain = domain.trim();
const baseName = $('Naming Conventions API').item.json.name;
const baseSlug = $('Naming Conventions API').item.json.slug;
const runSuffix = Date.now().toString().slice(-4);

return {
  sessionId: $('CMS & MM Login').item.json.sessionId,
  name: `${baseName} ${runSuffix}`,
  slug: `${baseSlug}-${runSuffix}`,

  brandCode: brandCode,
  brandName: brandName,
  region: region,
  regionId: regionId,
  bucket: bucket,
  territory: territory,

  playerId: playerId,
  audienceCode: audienceCode,

  domain: cleanDomain,
  loginUrl: `https://services.${cleanDomain}/services/login-service/v1/login`,
  previewUrl: `https://preview.${cleanDomain}/account/messages`,
  cookieDomain: `.${cleanDomain}`
};

