const brand = String($('OSN Dynamic Fields Mapping').item.json.brandCode || '').trim();
const region = String($('OSN Dynamic Fields Mapping').item.json.region || 'UFM').trim();
const playerId = String($('OSN Dynamic Fields Mapping').item.json.playerId || '').trim();
const audienceCode = String($('OSN Dynamic Fields Mapping').item.json.audienceCode || '').trim();

if (!playerId || !audienceCode || playerId === '[object Object]' || audienceCode === '[object Object]') {
  throw new Error(`Invalid data to generate CSV. PlayerID: "${playerId}", AudienceCode: "${audienceCode}"`);
}

// Added strict CRLF \r\n and trailing newline required by some Java parsers
const csvString = `AUDIENCE_CODE,PLAYER_ID\r\n${audienceCode},${playerId}\r\n`;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(csvString, 'utf-8'),
  `${brand}-${region}.csv`,
  'text/csv'
);

return {
  json: {
    fileName: `${brand}-${region}.csv`,
    audienceCode,
    playerId
  },
  binary: {
    audience_csv: binaryData
  }
};

const uploadRes = $('MM > Upload Audience').item.json;
const jobId = uploadRes.jobId || uploadRes.id;

if (!jobId) {
  throw new Error('Valid jobId was not received when uploading audience to MM.');
}

return {
  json: {
    jobId: jobId,
    retryCount: 0
  }
};

const status = String($json.status || '').toUpperCase();
const context = $('Prepare Loop Context').item.json;
context.retryCount = (context.retryCount || 0) + 1;

const MAX_RETRIES = 12;

if (status === 'FAILED' || status === 'ERROR') {
  throw new Error(`Audience upload failed in MM with status: "${status}"`);
}

if (context.retryCount > MAX_RETRIES) {
  throw new Error(`Timeout in MM: Audience status remained "${status || 'UNKNOWN'}" after ${MAX_RETRIES * 5} seconds.`);
}

return { json: context };

