const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default async ({ page, context }) => {
  await page.setViewport({ width: 1440, height: 750 });

  await page.setCookie(
    { name: 'sessionId', value: context.sessionId, domain: context.domain },
    { name: 'sid', value: context.sessionId, domain: context.domain }
  );

  // Extract base origin (e.g. https://preview.domain.lv/) to prevent navigating to subroutes like /account/messages
  const targetUrl = new URL(context.url).origin + '/';

  await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 15000 });

  // Force active tab visibility and window focus
  await page.bringToFront();
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { value: false, writable: true });
    Object.defineProperty(document, 'visibilityState', { value: 'visible', writable: true });
    document.dispatchEvent(new Event('visibilitychange'));
    window.dispatchEvent(new Event('focus'));
  });

  // Simulate user interaction to trigger idle/visibility listeners
  await page.mouse.move(500, 300);
  await page.mouse.wheel({ deltaY: 100 });
  await sleep(300);
  await page.mouse.wheel({ deltaY: -100 });

  // Wait specifically for visible notification popup or fail execution
  const selector = 'div.ol-notification__root';
  try {
    await page.waitForSelector(selector, { visible: true, timeout: 15000 });
  } catch (err) {
    throw new Error(`Target notification popup element "${selector}" was not found or not visible within 15 seconds on ${page.url()}`);
  }

  await sleep(1500);

  const screenshot = await page.screenshot({ encoding: 'base64' });
  return { data: { screenshot }, type: 'application/json' };
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default async ({ page, context }) => {
  await page.setViewport({ width: 1440, height: 750 });

  await page.setCookie(
    { name: 'sessionId', value: context.sessionId, domain: context.domain },
    { name: 'sid', value: context.sessionId, domain: context.domain }
  );

  await page.goto(context.url, { waitUntil: 'networkidle2' });

  await page.waitForSelector(
    'a.ol-responsive-button[href="/account/cashier/deposit"]',
    { timeout: 15000 }
  );
  await sleep(3000);

  await page.evaluate(() => {
    const container = document.querySelector('[data-surface="accountPanelSection"]')
      || document.querySelector('[data-surface="accountPanelSubContent"]');
    const target = [...container.querySelectorAll('button.ol-tab_item')]
      .find((button) => button.textContent.includes('Notifications'));
    if (!target) throw new Error('Notifications tab was not found');
    target.click();
  });

  await sleep(5000);
  await page.waitForSelector('tr.ol-table__row', { timeout: 15000 });

  await page.evaluate(() => {
    const tables = [...document.querySelectorAll('.ol-table__scrollableContainer')];
    for (const table of tables) {
      if (table.offsetParent === null) continue;
      const row = table.querySelector('tr.ol-table__row') || table.querySelector('tr.ol-table__row[data-index="0"]');
      if (row) {
        row.scrollIntoView({ block: 'center' });
        row.click();
        return;
      }
    }
    throw new Error('First notification row was not found');
  });

  await sleep(3000);

  const screenshot = await page.screenshot({ encoding: 'base64' });
  return { data: { screenshot }, type: 'application/json' };
};

